<script setup lang="ts">
import {localize} from './localization';

import {inject,ref} from 'vue';
import LabelEditor from './LabelEditor.vue';
import AllowancePanel from './AllowancePanel.vue';
import AdvancedTools from './AdvancedTools.vue';
import {resolvePiece} from '../../../packages/manufacturing/material';
import {usePatternContext} from './modules/patternEditorContext';
const advanced=inject('advancedMode',ref(false));
const {openJobs,store,language,t,stage,project,selectedId,selected,geometry,selectedNode,nodeX,nodeY,candidateDistance,candidateJoin,bounds,fmt,label,importSvg,offsetCandidate,startHole,changeTool,rectangle,circle,startOpenPath,update,resize,transform,duplicate,remove,applyNode}=usePatternContext();
</script>
<template><section v-show="stage==='pattern'" class="pattern-properties"><template v-if="selected"><div class="property-body"><div class="piece-badge">{{selected.name}}<small v-if="advanced">{{selected.id.slice(0,8)}}</small></div><label>{{language==='zh'?'裁片颜色':localize('Piece color')}}<input type="color" :value="selected.color" @change="update('color',($event.target as HTMLInputElement).value)"></label><label>{{t.name}}<input :value="selected.name" @change="update('name',($event.target as HTMLInputElement).value)"></label><div class="two-col"><label>{{t.width}} <span>mm</span><input type="number" min="0.001" step="0.1" :value="Number(bounds.w.toFixed(3))" @change="resize('xMm',Number(($event.target as HTMLInputElement).value))"></label><label>{{t.height}} <span>mm</span><input type="number" min="0.001" step="0.1" :value="Number(bounds.h.toFixed(3))" @change="resize('yMm',Number(($event.target as HTMLInputElement).value))"></label></div><div class="two-col"><button @click="transform('rotate')">{{t.rotate}}</button><button @click="transform('mirror')">{{t.flip}}</button></div><details class="property-group"><summary>{{language==='zh'?'缝份':localize('Seam allowance')}}</summary><label>{{t.allowance}} <span>mm</span><input type="number" min="0" max="1000" step="0.5" v-model.number="candidateDistance"></label><label v-if="advanced">{{language==='zh'?'缝份连接':localize('Allowance join')}}<select v-model="candidateJoin"><option value="miter">{{language==='zh'?'尖角':localize('Miter')}}</option><option value="round">{{language==='zh'?'圆角':localize('Round')}}</option><option value="bevel">{{language==='zh'?'倒角':localize('Bevel')}}</option></select></label><button class="allowance-candidate" :disabled="store.busy" @click="offsetCandidate">{{language==='zh'?'生成缝份候选':localize('Generate allowance candidate')}}</button><small class="accepted-allowance">{{language==='zh'?'已采用':localize('Accepted')}}: {{project?resolvePiece(project,selected).allowanceMm:selected.allowanceMm}} mm</small></details><details class="property-group"><summary>{{language==='zh'?'材料与裁剪':localize('Material & cutting')}}</summary><label>{{t.material}}<input :value="selected.material" @change="update('material',($event.target as HTMLInputElement).value)"></label><div class="two-col"><label>{{t.quantity}}<input type="number" min="1" max="100" :value="selected.cutQty" @change="update('cutQty',Number(($event.target as HTMLInputElement).value))"></label><label>{{t.fur}} <span>°</span><input type="number" :value="selected.furRad*180/Math.PI" @change="update('furRad',Number(($event.target as HTMLInputElement).value)*Math.PI/180)"></label></div><label v-if="advanced">{{language==='zh'?'布向角 °（留空表示未知）':localize('Grain angle ° (blank = unknown)')}}<input type="number" :value="selected.grainRad===undefined?'':selected.grainRad*180/Math.PI" @change="update('grainRad',($event.target as HTMLInputElement).value===''?undefined:Number(($event.target as HTMLInputElement).value)*Math.PI/180)"></label><label class="check-label"><input type="checkbox" :checked="selected.mirror" @change="update('mirror',($event.target as HTMLInputElement).checked)">{{t.mirror}}</label></details><dl v-if="advanced"><dt>{{t.area}}</dt><dd>{{fmt(geometry?.areaMm2??0)}} mm²</dd><dt>{{t.perimeter}}</dt><dd>{{fmt(geometry?.perimeterMm??0)}} mm</dd></dl><template v-if="advanced&&selectedNode"><hr><div class="two-col"><label>{{t.x}}<input v-model.number="nodeX" type="number" step="0.1"></label><label>{{t.y}}<input v-model.number="nodeY" type="number" step="0.1"></label></div><button @click="applyNode">{{t.applyNode}}</button></template><details v-if="advanced" class="property-group"><summary>{{language==='zh'?'逐边缝份':localize('Edge allowances')}}</summary><AllowancePanel :piece="selected" :node-id="selectedNode" :language="language" @jobs="openJobs()"/></details><LabelEditor v-if="advanced" :piece="selected" :language="language"/><AdvancedTools v-if="advanced" :piece="selected" :node-id="selectedNode" :language="language" @select="selectedId=$event" @hole="startHole"/><div class="two-col bottom-actions"><button class="danger" @click="remove">{{t.delete}}</button></div></div></template><div v-else class="inspector-empty"><span>◇</span><p>{{t.choose}}</p><small>{{language==='zh'?'从右侧裁片列表选择，或在左侧二维预览中点击裁片。':localize('Choose a piece from the right list or the 2D preview on the left.')}}</small></div></section></template>
